                    }
                }
                a = min(a, x);
                b = max(b, x);
            }
            return vector<int>{cnt, max(1, b - a)};
        };

        vector<int> r0 = f(0);
        vector<int> r1 = f(1);

        return r0 < r1 ? r0 : r1;
    }
};

function makeParityAlternating(nums: number[]): number[] {
    if (nums.length === 1) {
        return [0, 0];
    }

    const mn = Math.min(...nums);
    const mx = Math.max(...nums);

    const f = (k: number): number[] => {
