class Solution:
    def maxValue(self, nums1: list[int], nums0: list[int]) -> int:
        MOD = 10**9 + 7
        pairs = list(zip(nums1, nums0))
        b = sum(x + y for x, y in pairs)

        def key(p: tuple[int, int]) -> tuple[int, int, int]:
            x, y = p
            if y == 0:
                return (0, -x, 0)
            if x > 0:
                return (1, -x, y)
            return (2, y, 0)

        pairs.sort(key=key)

        ans = 0
        p = [1] * b
        for i in range(1, b):
            p[i] = p[i - 1] * 2 % MOD

        b -= 1
        for cnt1, cnt0 in pairs:
            while cnt1:
                ans = (ans + p[b]) % MOD
                b -= 1
                cnt1 -= 1
            b -= cnt0
        return ans

class Solution {
public:
    static constexpr int MOD = 1'000'000'007;

    int maxValue(vector<int>& nums1, vector<int>& nums0) {
        vector<pair<int, int>> pairs;
        int b = 0;
        for (int i = 0; i < nums1.size(); ++i) {
            pairs.emplace_back(nums1[i], nums0[i]);
            b += nums1[i] + nums0[i];
        }

        sort(pairs.begin(), pairs.end(), [](const auto& a, const auto& b) {
            auto group = [](const pair<int, int>& p) {
                if (p.second == 0) {
                    return 0;
                }
                if (p.first > 0) {
                    return 1;
                }
                return 2;
            };

            int g1 = group(a), g2 = group(b);
            if (g1 != g2) {
                return g1 < g2;
            }
            if (g1 == 0) {
                return a.first > b.first;
            }
            if (g1 == 1) {
                if (a.first != b.first) {
                    return a.first > b.first;
                }
                return a.second < b.second;
            }
            return a.second < b.second;
        });

        vector<long long> p(b, 1);
        for (int i = 1; i < b; ++i) {
            p[i] = p[i - 1] * 2 % MOD;
        }

        long long ans = 0;
        --b;
        for (auto& [cnt1, cnt0] : pairs) {
            while (cnt1--) {
                ans = (ans + p[b--]) % MOD;
            }
            b -= cnt0;
        }
        return (int) ans;
    }
};

function maxValue(nums1: number[], nums0: number[]): number {
    const MOD = 1_000_000_007;
    const pairs: [number, number][] = [];
    let b = 0;

    for (let i = 0; i < nums1.length; ++i) {
        pairs.push([nums1[i], nums0[i]]);
        b += nums1[i] + nums0[i];
    }

    const group = ([x, y]: [number, number]): number => {
        if (y === 0) {
            return 0;
        }
        if (x > 0) {
            return 1;
        }
        return 2;
    };

    pairs.sort((a, c) => {
        const g1 = group(a);
        const g2 = group(c);
        if (g1 !== g2) {
            return g1 - g2;
        }
        if (g1 === 0) {
            return c[0] - a[0];
        }
        if (g1 === 1) {
            if (a[0] !== c[0]) {
                return c[0] - a[0];
            }
            return a[1] - c[1];
        }
        return a[1] - c[1];
    });

    const p = Array<number>(b).fill(1);
    for (let i = 1; i < b; ++i) {
        p[i] = (p[i - 1] * 2) % MOD;
    }

    let ans = 0;
    --b;
    for (let [cnt1, cnt0] of pairs) {
        while (cnt1 > 0) {
            ans = (ans + p[b]) % MOD;
            --b;
            --cnt1;
        }
        b -= cnt0;
    }
    return ans;
}

